s.text="      (function() {\n        try {\n          // Debouncing and duplicate filtering for JS\n          var isSending = false;\n          var debounceTimer = null;\n          var recentLogs = new Map();\n          var pendingLogs = [];\n          var DEBOUNCE_DURATION = 500; // 500ms\n          var DUPLICATE_WINDOW = 5000; // 5 seconds\n\n          function send(type, message) {\n            if (isSending) return; // Prevent recursion during flush\n\n            try {\n              var logKey = type + ':' + String(message);\n              var now = Date.now();\n\n              // Check for duplicates within the duplicate window\n              if (recentLogs.has(logKey)) {\n                var lastSent = recentLogs.get(logKey);\n                if (now - lastSent < DUPLICATE_WINDOW) {\n                  return; // Skip duplicate within time window\n                }\n              }\n\n              // Add to pending logs\n              pendingLogs.push({\n                type: type,\n                message: String(message),\n                timestamp: new Date().toISOString(),\n                url: window.location.href,\n                logKey: logKey,\n                addedAt: now\n              });\n\n              // Cancel existing timer and start new one\n              if (debounceTimer) {\n                clearTimeout(debounceTimer);\n              }\n              debounceTimer = setTimeout(flushPendingLogs, DEBOUNCE_DURATION);\n\n            } catch (_) {\n              // Clear pending logs on error to prevent accumulation\n              pendingLogs = [];\n            }\n          }\n\n          function flushPendingLogs() {\n            if (pendingLogs.length === 0 || isSending) return;\n\n            isSending = true;\n            var now = Date.now();\n\n            try {\n              // Remove duplicates and send each unique log\n              var logsToSend = [];\n              var seen = new Set();\n\n              for (var i = 0; i < pendingLogs.length; i++) {\n                var logData = pendingLogs[i];\n                var logKey = logData.logKey;\n\n                if (!seen.has(logKey)) {\n                  seen.add(logKey);\n                  recentLogs.set(logKey, now);\n\n                  // Remove logKey from payload before sending\n                  var payload = {\n                    type: logData.type,\n                    message: logData.message,\n                    timestamp: logData.timestamp,\n                    url: logData.url\n                  };\n                  logsToSend.push(payload);\n                }\n              }\n\n              // Send all unique logs\n              var promises = [];\n              for (var j = 0; j < logsToSend.length; j++) {\n                var promise = fetch('https://shopstock1574back.builtwithrocket.new/logs', {\n                  method: 'POST',\n                  headers: { 'Content-Type': 'application/json' },\n                  body: JSON.stringify(logsToSend[j])\n                }).catch(function(_) {}); // Ignore fetch errors\n                promises.push(promise);\n              }\n\n              // Wait for all requests to complete\n              Promise.all(promises).finally(function() {\n                isSending = false;\n              });\n\n              // Clean up old entries from recent logs (older than DUPLICATE_WINDOW)\n              var keysToDelete = [];\n              recentLogs.forEach(function(time, key) {\n                if (now - time > DUPLICATE_WINDOW) {\n                  keysToDelete.push(key);\n                }\n              });\n              for (var k = 0; k < keysToDelete.length; k++) {\n                recentLogs.delete(keysToDelete[k]);\n              }\n\n            } catch (_) {\n              isSending = false;\n            } finally {\n              pendingLogs = []; // Clear pending logs\n              debounceTimer = null;\n            }\n          }\n\n          // Capture Dart prints in debug (DDC)\n          try {\n      var originalDartPrint = window.dartPrint;\n      window.dartPrint = function (message) {\n        // Call original dartPrint first - more robust calling\n        try {\n          if (originalDartPrint && typeof originalDartPrint === \"function\") {\n            originalDartPrint.call(window, message);\n          } else {\n            // Fallback to console.log if originalDartPrint not available\n            console.log(message);\n          }\n        } catch (_) {\n          // Fallback if original fails\n          console.log(message);\n        }\n        send(\"CONSOLE_LOG\", message);\n      };\n    } catch (_) {}\n\n          // Capture console methods (release/profile and any JS logs)\n          var originalLog = console.log;\n          var originalError = console.error;\n          var originalWarn = console.warn;\n          var originalInfo = console.info;\n          var originalDebug = console.debug;\n\n          console.log = function() {\n            originalLog.apply(console, arguments);\n            try { send('CONSOLE_LOG', Array.prototype.join.call(arguments, ' ')); } catch(_) {}\n          };\n          console.error = function() {\n            originalError.apply(console, arguments);\n            try { send('CONSOLE_ERROR', Array.prototype.join.call(arguments, ' ')); } catch(_) {}\n          };\n          console.warn = function() {\n            originalWarn.apply(console, arguments);\n            try { send('CONSOLE_WARN', Array.prototype.join.call(arguments, ' ')); } catch(_) {}\n          };\n          console.info = function() {\n            originalInfo.apply(console, arguments);\n            try { send('CONSOLE_INFO', Array.prototype.join.call(arguments, ' ')); } catch(_) {}\n          };\n          console.debug = function() {\n            originalDebug.apply(console, arguments);\n            try { send('CONSOLE_DEBUG', Array.prototype.join.call(arguments, ' ')); } catch(_) {}\n          };\n        } catch (_) { /* noop */ }\n      })();\n    "
